function createEnv(sdk) {
  var STEPS = 1200;
  var DT = 1 / 60;
  var rng, x, xDot, angle, angleDot, t, done;
  var terms = [0, 0, 0, 0];
  var obs = [0, 0, 0, 0, 0];

  function difficulty() {
    return Math.min(1, t / STEPS);
  }

  function trackLimit() {
    return 2.4 - 0.5 * difficulty();
  }

  function reset(seed) {
    rng = sdk.rng(seed);
    x = 0;
    xDot = 0;
    angle = rng.range(-0.035, 0.035);
    angleDot = rng.range(-0.02, 0.02);
    t = 0;
    done = false;
    terms[0] = 0;
    terms[1] = 0;
    terms[2] = 0;
    terms[3] = 0;
  }

  return {
    reset: reset,

    step: function (action) {
      if (done) return;

      var force = 0;
      if (action === 0) force = -10;
      else if (action === 2) force = 10;

      var diff = difficulty();
      var gravity = 9.8 * (1 + 0.18 * diff);
      var poleMass = 0.1;
      var cartMass = 1;
      var totalMass = poleMass + cartMass;
      var halfPoleLength = 0.5;
      var poleMassLength = poleMass * halfPoleLength;
      var sinAngle = Math.sin(angle);
      var cosAngle = Math.cos(angle);

      var temp = (force + poleMassLength * angleDot * angleDot * sinAngle) / totalMass;
      var angleAcc = (gravity * sinAngle - cosAngle * temp) /
        (halfPoleLength * (4 / 3 - poleMass * cosAngle * cosAngle / totalMass));
      var cartAcc = temp - poleMassLength * angleAcc * cosAngle / totalMass;

      xDot += cartAcc * DT;
      xDot *= 0.999;
      angleDot += angleAcc * DT;
      angleDot *= 0.999;
      x += xDot * DT;
      angle += angleDot * DT;
      t += 1;

      var dt = DT;
      var angleQuality = Math.exp(-Math.pow(angle / 0.24, 2) - Math.pow(angleDot / 2.5, 2));
      var centerScale = Math.max(0.5, trackLimit() * 0.6);
      var centerQuality = Math.exp(-Math.pow(x / centerScale, 2));
      terms[0] += dt;
      terms[1] += angleQuality * dt;
      terms[2] += centerQuality * dt;
      if (force !== 0) terms[3] += dt;

      var angleLimit = 0.48 - 0.08 * diff;
      if (Math.abs(angle) > angleLimit || Math.abs(x) > trackLimit() || t >= STEPS) {
        done = true;
      }
    },

    observe: function () {
      obs[0] = sdk.clamp(x / 2.4, -1, 1);
      obs[1] = sdk.clamp(xDot / 4, -1, 1);
      obs[2] = sdk.clamp(angle / 0.6, -1, 1);
      obs[3] = sdk.clamp(angleDot / 6, -1, 1);
      obs[4] = difficulty();
      return obs;
    },

    get done() {
      return done;
    },

    terms: terms,

    render: function (draw, ghost) {
      var scale = 120;
      var cartX = 400 + x * scale;
      var cartY = 365;
      var pivotX = cartX;
      var pivotY = cartY - 16;
      var poleLength = 115;
      var tipX = pivotX + Math.sin(angle) * poleLength;
      var tipY = pivotY - Math.cos(angle) * poleLength;

      if (!ghost) {
        draw.clear(sdk.colors.bg);
        var limit = trackLimit();
        var left = 400 - limit * scale;
        var right = 400 + limit * scale;
        draw.line(left, 390, right, 390, sdk.colors.dim, 4);
        draw.line(left, 390, left, 405, sdk.colors.dim, 3);
        draw.line(right, 390, right, 405, sdk.colors.dim, 3);
        draw.line(400, 385, 400, 395, sdk.colors.dim, 1);
        draw.text("BALANCE", 24, 32, sdk.colors.fg, 18);
        draw.text("difficulty " + Math.round(difficulty() * 100) + "%", 24, 55, sdk.colors.dim, 13);
      }

      draw.line(pivotX, pivotY, tipX, tipY, sdk.colors.accent, 7);
      draw.circle(tipX, tipY, 7, sdk.colors.warn);
      draw.rect(cartX - 28, cartY - 16, 56, 28, sdk.colors.good);
      draw.circle(cartX - 17, cartY + 14, 7, sdk.colors.fg);
      draw.circle(cartX + 17, cartY + 14, 7, sdk.colors.fg);
      draw.circle(pivotX, pivotY, 6, sdk.colors.accent);
    },

    humanAct: function (input) {
      if (input.held.has("ArrowLeft")) return 0;
      if (input.held.has("ArrowRight")) return 2;
      return 1;
    }
  };
}
